function makeQ(lo:number,row:Row,i:number,caseId?:string):Question {const [stem,right,w1,w2,w3,explanation]=row;const bank=[right,w1,w2,w3];const shift=(i*7+lo)%4;const options=[...bank.slice(shift),...bank.slice(0,shift)] as [string,string,string,string];return {id:caseId?`${caseId}-${i+1}`:`q${lo}-${i+1}`,lo,stem,options,correct:options.indexOf(right),explanation,incorrectWhy:`The other options are inconsistent with the stated facts or confuse this concept with a different duty, product or calculation. ${explanation}`,difficulty:(i%5===0?'Hard':i%3===0?'Medium':'Easy'),lessonId:`lo${lo}`,changeable:/tax|scheme|SMI|regulat|fca|MCOB|tenure|leasehold|LBTT|LTT|SDLT|state|arrears|consent|credit|buyer/i.test(stem),caseId,trap:/\b(NOT|LEAST|MOST|EXCEPT|best|first|main|chief)\b/i.test(stem)};}
