export function validateQuestions():string[]{const errors:string[]=[];const ids=new Set<string>();for(const q of questions){if(ids.has(q.id))errors.push(`Duplicate ${q.id}`);ids.add(q.id);if(q.options.length!==4||new Set(q.options).size!==4)errors.push(`Invalid options ${q.id}`);if(q.correct<0||q.correct>3||!q.options[q.correct])errors.push(`Invalid key ${q.id}`);if(!q.explanation||!q.incorrectWhy||q.lo<1||q.lo>16)errors.push(`Missing rationale ${q.id}`)}for(let lo=1;lo<=15;lo++){if(standaloneQuestions.filter(q=>q.lo===lo).length!==examWeights[lo-1])errors.push(`LO${lo} count ${standaloneQuestions.filter(q=>q.lo===lo).length} vs ${examWeights[lo-1]}`);}return errors;}
